ALTER TABLE "wb_next"."drama_projects" ADD CONSTRAINT "drama_project_mode_data" CHECK (("wb_next"."drama_projects"."mode" = 'idea' and length(btrim("wb_next"."drama_projects"."idea")) between 1 and 1000 and (("wb_next"."drama_projects"."script_id" is null and "wb_next"."drama_projects"."active_version_id" is null and "wb_next"."drama_projects"."confirmed_version_id" is null) or ("wb_next"."drama_projects"."script_id" is not null and "wb_next"."drama_projects"."active_version_id" is not null and "wb_next"."drama_projects"."confirmed_version_id" is not null and "wb_next"."drama_projects"."confirmed_version_id" = "wb_next"."drama_projects"."active_version_id")) and "wb_next"."drama_projects"."genre" in ('通用', '动作', '玄幻', '言情', '悬疑', '古装', '现代', '穿越', '重生', '都市', '宫斗', '喜剧', '科幻', '校园', '青春') and "wb_next"."drama_projects"."tone" in ('通用', '严肃', '搞笑', '讽刺', '稳重', '简洁')) or ("wb_next"."drama_projects"."mode" = 'script' and "wb_next"."drama_projects"."idea" is null and "wb_next"."drama_projects"."script_id" is not null and "wb_next"."drama_projects"."active_version_id" is not null and "wb_next"."drama_projects"."genre" is null and "wb_next"."drama_projects"."tone" is null));